import{Z as t,e as i,f as a,a0 as n}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Iterable","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/email-marketing/iterable.md","filePath":"integrations/email-marketing/iterable.md","lastUpdated":1780377007000}'),o={name:"integrations/email-marketing/iterable.md"};function r(s,e,l,h,c,d){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="iterable" tabindex="-1">Iterable <a class="header-anchor" href="#iterable" aria-label="Permalink to &quot;Iterable&quot;">​</a></h1><p>Connect Iterable to send newsletter sign-ups to your chosen mailing list. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Email Marketing</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Iterable as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-iterable-api" tabindex="-1">Step 2. Connect to the Iterable API <a class="header-anchor" href="#step-2-connect-to-the-iterable-api" aria-label="Permalink to &quot;Step 2. Connect to the Iterable API&quot;">​</a></h3><ol><li>Go to <a href="https://app.iterable.com" target="_blank">Iterable</a> and login to your account.</li><li>In the top menu, click <strong>Integrations</strong> and <strong>API Keys</strong>.</li><li>Click the <strong>New API Key</strong> button.</li><li>Enter a <strong>Name</strong> and select <strong>Server-side</strong> for the API key type.</li><li>Click <strong>Create</strong>.</li><li>Copy the <strong>API Key</strong> from Iterable and paste it into the <strong>API Key</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Select the destination list and map its required email field to your form’s Email Address field. Map any additional fields your list requires using the variable picker. If you collect a newsletter opt-in, configure integration conditions so only visitors who choose it are sent.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h3 id="additional-features" tabindex="-1">Additional Features <a class="header-anchor" href="#additional-features" aria-label="Permalink to &quot;Additional Features&quot;">​</a></h3><ul><li>Supports mapping to Iterable user fields returned by your project.</li></ul><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Look up the test email in the selected list and check its mapped values and subscription state. If the provider requires confirmation, complete that step before expecting an active subscription.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',15)])])}const u=t(o,[["render",r]]);export{p as __pageData,u as default};
